module FSM(input CLK, X, Y, output reg Z); 
  reg [1:0] current_state, next_state; 
  parameter A = 2'b01, B = 2'b10; 
  always @(posedge CLK) begin 
    current_state <= next_state; 
  end 
  always @(*) begin 
    case (current_state) 
      A: if (X && Y) next_state = B; else next_state = A; 
      B: if (!X && !Y) next_state = A; else next_state = B; 
      default: next_state = A; 
    endcase 
  end 
  always @(*) begin 
    case (current_state) 
      A: Z = 0; 
      B: Z = 1; 
      default: Z = 0; 
    endcase 
  end 
endmodule
